// Tabel warga untuk dashboard petugas (tanpa menampilkan Chat ID)
const warga = global.get('sideban_warga') || {};
const pelanggan = (global.get('sideban_pelanggan') || []).map(String);
const baris = Object.keys(warga).filter(id => pelanggan.includes(id)).map(id => {
    const w = warga[id];
    return {
        'Kode': w.kode,
        'Kategori rumah': w.kategori,
        'Batas (cm)': w.batas_cm,
        'Kondisi': w.terpicu ? '⚠️ Terlampaui' : '✅ Aman'
    };
}).sort((a, b) => a.Kode.localeCompare(b.Kode));
const hitung = {rendah: 0, sedang: 0, tinggi: 0, khusus: 0};
for (const b of baris) hitung[b['Kategori rumah']] = (hitung[b['Kategori rumah']] || 0) + 1;
return [
    {payload: baris},
    {payload: `Rendah ${hitung.rendah} · Sedang ${hitung.sedang} · Tinggi ${hitung.tinggi} · Khusus ${hitung.khusus}`}
];

// ===== PENGATURAN BOT TELEGRAM =====
// Isi dengan Chat ID petugas/admin (boleh lebih dari satu).
// Cara tahu Chat ID: kirim /id ke bot kamu.
// Hanya admin yang boleh /bisukan, /aktifkan, dan mengubah /ambang.
const ADMIN_CHAT_ID = [
    // 123456789,
];

// ===== BATAS PRIBADI SESUAI KETINGGIAN RUMAH =====
// Angka = jarak sensor ke permukaan air (cm). Makin kecil = air makin tinggi.
// Warga rumah RENDAH diberi peringatan paling awal (jarak masih jauh).
// Nilai ini untuk demo meja; sesuaikan setelah kalibrasi di lokasi.
const BATAS_RUMAH = {
    rendah: 120,
    sedang: 80,
    tinggi: 40,
};

global.set('sideban_admin', ADMIN_CHAT_ID);
global.set('sideban_batas_rumah', BATAS_RUMAH);
const pelanggan = global.get('sideban_pelanggan') || [];
global.set('sideban_pelanggan', pelanggan);

// Warga yang memilih kategori ikut memakai angka terbaru di atas
const warga = global.get('sideban_warga') || {};
const keMqtt = [];
for (const id of Object.keys(warga)) {
    const w = warga[id];
    if (BATAS_RUMAH[w.kategori] !== undefined && w.batas_cm !== BATAS_RUMAH[w.kategori]) {
        w.batas_cm = BATAS_RUMAH[w.kategori];
        w.terpicu = false;
        keMqtt.push({topic: `sideban/titik01/warga/${w.kode}/batas`,
                     payload: JSON.stringify({kategori: w.kategori, batas_cm: w.batas_cm})});
    }
}
global.set('sideban_warga', warga);

node.status({fill: 'green', shape: 'dot', text: `admin: ${ADMIN_CHAT_ID.length}, warga: ${pelanggan.length}`});
return [{payload: pelanggan.length}, keMqtt, {payload: 'refresh'}];

// Pesan status dari ESP32 (retained) -> teks dashboard
const s = msg.payload;
if (typeof s !== 'object' || s === null || typeof s.level !== 'number') return null;

global.set('sideban_status', s);
global.set('sideban_status_waktu', Date.now());

const ikon = {AMAN: '🟢', SIAGA: '🟡', BAHAYA: '🔴'}[s.status] || '⚪';
const ambang = s.ambang || {};
return [
    {payload: `${ikon} ${s.status}`},
    {payload: `${s.jarak_cm} cm · hujan ${s.hujan_persen}% (${s.hujan})`},
    {payload: s.buzzer === 'MUTE' ? '🔕 Dibisukan' : '🔔 Otomatis'},
    {payload: `Bahaya ≤ ${ambang.bahaya} cm · Siaga ≤ ${ambang.siaga} cm · Deras > ${ambang.deras}%`}
];

// Kirim peringatan saat status berubah.
// Naik level (AMAN->SIAGA->BAHAYA) = langsung dikirim.
// Turun level harus terbaca 2x berturut-turut, supaya tidak spam saat nilai naik-turun.
const s = msg.payload;
if (!s || typeof s.level !== 'number') return null;
const L = s.level;
const terakhir = global.get('sideban_level_alert');

if (terakhir === undefined) {          // pertama kali jalan: simpan saja
    global.set('sideban_level_alert', L);
    return null;
}
if (L === terakhir) {
    context.set('pending', null);
    return null;
}
if (L < terakhir && context.get('pending') !== L) {
    context.set('pending', L);
    return null;
}
context.set('pending', null);
global.set('sideban_level_alert', L);

const waktu = new Date().toLocaleString('id-ID', {timeZone: 'Asia/Jakarta'});
let teks;
if (L === 2) {
    teks = `🚨 BAHAYA BANJIR - Titik 01\n` +
           `Jarak sensor ke air: ${s.jarak_cm} cm\n` +
           `Hujan: ${s.hujan_persen}% (${s.hujan})\n` +
           `Waktu: ${waktu}\n\n` +
           `Amankan barang dan dokumen penting, siapkan evakuasi, dan ikuti arahan petugas.`;
} else if (L === 1) {
    teks = `⚠️ SIAGA - Titik 01\n` +
           `Jarak sensor ke air: ${s.jarak_cm} cm\n` +
           `Hujan: ${s.hujan_persen}% (${s.hujan})\n` +
           `Waktu: ${waktu}\n\n` +
           `Air mulai naik atau hujan deras. Pantau terus perkembangan.`;
} else {
    teks = `✅ Kembali AMAN - Titik 01\n` +
           `Jarak sensor ke air: ${s.jarak_cm} cm\n` +
           `Waktu: ${waktu}`;
}

const pelanggan = global.get('sideban_pelanggan') || [];
const keTelegram = pelanggan.map(id => ({payload: {chatId: id, type: 'message', content: teks}}));
node.status({fill: L === 2 ? 'red' : (L === 1 ? 'yellow' : 'green'), shape: 'dot',
             text: `${s.status} -> ${pelanggan.length} warga`});
return [keTelegram, {payload: teks.split('\n')[0]}];

// online / offline dari Last Will ESP32
const st = String(msg.payload).trim().toLowerCase();
const sebelum = global.get('sideban_perangkat');
global.set('sideban_perangkat', st);

const ui = {payload: st === 'online' ? '✅ Online' : '❌ Offline'};
if (sebelum === undefined || sebelum === st) return [ui, null];

const teks = st === 'online'
    ? '✅ Perangkat SIDEBAN titik 01 kembali online.'
    : '❌ Perangkat SIDEBAN titik 01 OFFLINE (listrik atau WiFi putus). Data tidak terpantau sampai perangkat online lagi.';
const admin = global.get('sideban_admin') || [];
return [ui, admin.map(id => ({payload: {chatId: id, type: 'message', content: teks}}))];

const j = Number(msg.payload && msg.payload.jarak_cm);
if (!Number.isFinite(j)) return null;
return {payload: j, topic: 'Jarak (cm)'};

const h = msg.payload || {};
const p = Number(h.persen);
if (!Number.isFinite(p)) return null;
return [{payload: p, topic: 'Hujan (%)'}, {payload: `${h.kategori} (ADC ${h.adc})`}];

function validasiAmbang(b, s, d) {
    if (![b, s, d].every(Number.isInteger)) return 'Semua nilai harus bilangan bulat.';
    if (b < 2) return 'Ambang bahaya minimal 2 cm.';
    if (s <= b) return 'Ambang siaga harus lebih besar dari ambang bahaya.';
    if (s > 400) return 'Ambang siaga maksimal 400 cm.';
    if (d <= 15 || d > 100) return 'Batas hujan deras harus 16-100 %.';
    return null;
}

const b = Number(msg.payload.bahaya);
const s = Number(msg.payload.siaga);
const d = Number(msg.payload.deras);
const salah = validasiAmbang(b, s, d);
if (salah) return [null, {payload: '❌ ' + salah}];
return [
    {payload: JSON.stringify({bahaya: b, siaga: s, deras: d})},
    {payload: `✅ Ambang dikirim: bahaya ≤ ${b} cm, siaga ≤ ${s} cm, deras > ${d}%`}
];

function validasiAmbang(b, s, d) {
    if (![b, s, d].every(Number.isInteger)) return 'Semua nilai harus bilangan bulat.';
    if (b < 2) return 'Ambang bahaya minimal 2 cm.';
    if (s <= b) return 'Ambang siaga harus lebih besar dari ambang bahaya.';
    if (s > 400) return 'Ambang siaga maksimal 400 cm.';
    if (d <= 15 || d > 100) return 'Batas hujan deras harus 16-100 %.';
    return null;
}

// Output: 1 balasan Telegram | 2 perintah buzzer | 3 perintah ambang | 4 jumlah warga
//         5 batas warga ke MQTT | 6 segarkan tabel warga
const p = msg.payload || {};
if (p.type !== 'message' || typeof p.content !== 'string') return null;

const chatId = p.chatId;
const bagian = p.content.trim().split(/\s+/);
const perintah = (bagian[0] || '').toLowerCase().replace(/@.*$/, '');
const arg = bagian.slice(1);
const admin = (global.get('sideban_admin') || []).map(String).includes(String(chatId));
let pelanggan = global.get('sideban_pelanggan') || [];
const balas = isi => ({payload: {chatId: chatId, type: 'message', content: isi}});
const out = [null, null, null, null, null, null];
const BATAS_RUMAH = global.get('sideban_batas_rumah') || {rendah: 120, sedang: 80, tinggi: 40};
let warga = global.get('sideban_warga') || {};
const kunci = String(chatId);

function daftarkan() {
    if (!pelanggan.includes(chatId)) {
        pelanggan.push(chatId);
        global.set('sideban_pelanggan', pelanggan);
    }
    out[3] = {payload: pelanggan.length};
}
function simpanBatas(kategori, batas) {
    let w = warga[kunci];
    if (!w) {
        const urut = (global.get('sideban_warga_urut') || 0) + 1;
        global.set('sideban_warga_urut', urut);
        w = {kode: 'W' + String(urut).padStart(3, '0'), chatId: chatId};
    }
    w.kategori = kategori;
    w.batas_cm = batas;
    w.terpicu = false;
    w.diubah = Date.now();
    warga[kunci] = w;
    global.set('sideban_warga', warga);
    daftarkan();
    out[4] = {topic: `sideban/titik01/warga/${w.kode}/batas`,
              payload: JSON.stringify({kategori: kategori, batas_cm: batas})};
    out[5] = {payload: 'refresh'};
    return w;
}
function teksBatasku() {
    const w = warga[kunci];
    if (!w) return 'Kamu belum mengatur batas rumah.';
    return `Kode warga: ${w.kode}\nKategori rumah: ${w.kategori}\n` +
           `Peringatan pribadi saat jarak sensor ke air ≤ ${w.batas_cm} cm`;
}

const BANTUAN =
    'SIDEBAN - Sistem Deteksi Dini Banjir 🌊\n\n' +
    'Untuk warga:\n' +
    '/daftar - terima peringatan banjir\n' +
    '/berhenti - berhenti menerima peringatan\n' +
    '/status - lihat kondisi terkini\n' +
    '/id - lihat Chat ID kamu\n' +
    '/rumah rendah | sedang | tinggi - atur batas sesuai ketinggian rumah\n' +
    '/batas 90 - atur batas sendiri (cm)\n' +
    '/rumah - lihat batas rumah kamu\n\n' +
    'Untuk petugas (admin):\n' +
    '/bisukan - matikan buzzer di lokasi\n' +
    '/aktifkan - nyalakan buzzer otomatis lagi\n' +
    '/ambang - lihat ambang batas\n' +
    '/ambang 20 100 65 - ubah ambang (bahaya cm, siaga cm, deras %)';
const TOLAK = '⛔ Perintah ini khusus petugas. Minta petugas menambahkan Chat ID kamu (' + chatId + ').';

function teksStatus() {
    const s = global.get('sideban_status');
    const perangkat = global.get('sideban_perangkat') || 'tidak diketahui';
    if (!s) return 'Belum ada data dari perangkat.';
    const detik = Math.round((Date.now() - (global.get('sideban_status_waktu') || Date.now())) / 1000);
    const ikon = {AMAN: '🟢', SIAGA: '🟡', BAHAYA: '🔴'}[s.status] || '⚪';
    return `${ikon} Status: ${s.status}\n` +
           `Jarak sensor ke air: ${s.jarak_cm} cm\n` +
           `Hujan: ${s.hujan_persen}% (${s.hujan})\n` +
           `Buzzer: ${s.buzzer === 'MUTE' ? 'dibisukan' : 'otomatis'}\n` +
           `Perangkat: ${perangkat}\n` +
           `Diperbarui ${detik} detik lalu` +
           (warga[kunci] ? `\n\nBatas rumah kamu (${warga[kunci].kategori}): ${warga[kunci].batas_cm} cm` +
               (s.jarak_cm <= warga[kunci].batas_cm ? ' ⚠️ SUDAH TERLAMPAUI' : ' (belum terlampaui)') : '');
}

switch (perintah) {
    case '/start':
    case '/bantuan':
    case '/help':
        out[0] = balas(BANTUAN);
        break;
    case '/id':
        out[0] = balas(`Chat ID kamu: ${chatId}` + (admin ? ' (admin)' : ''));
        break;
    case '/daftar':
        daftarkan();
        out[0] = balas('✅ Kamu terdaftar. Peringatan banjir titik 01 akan dikirim ke chat ini.\n\n' +
                       'Atur juga batas sesuai ketinggian rumahmu supaya dapat peringatan pribadi:\n' +
                       '/rumah rendah, /rumah sedang, atau /rumah tinggi');
        break;
    case '/rumah': {
        const pilihan = (arg[0] || '').toLowerCase();
        if (!pilihan) {
            out[0] = balas(teksBatasku() + '\n\nPilihan:\n' +
                `/rumah rendah - lantai rumah rendah / dekat sungai (peringatan saat ≤ ${BATAS_RUMAH.rendah} cm)\n` +
                `/rumah sedang - (peringatan saat ≤ ${BATAS_RUMAH.sedang} cm)\n` +
                `/rumah tinggi - lantai rumah tinggi (peringatan saat ≤ ${BATAS_RUMAH.tinggi} cm)\n` +
                '/batas 90 - atur angka sendiri');
            break;
        }
        if (BATAS_RUMAH[pilihan] === undefined) {
            out[0] = balas('Pilihan tidak dikenal. Gunakan /rumah rendah, /rumah sedang, atau /rumah tinggi.');
            break;
        }
        simpanBatas(pilihan, BATAS_RUMAH[pilihan]);
        out[0] = balas('✅ Batas rumah disimpan.\n' + teksBatasku() +
                       '\nKamu juga tetap menerima peringatan umum SIAGA/BAHAYA.');
        break;
    }
    case '/batas': {
        if (arg.length === 0) { out[0] = balas(teksBatasku()); break; }
        const cm = Number(arg[0]);
        if (!Number.isInteger(cm) || cm < 2 || cm > 400) {
            out[0] = balas('Batas harus bilangan bulat 2-400 cm. Contoh: /batas 90');
            break;
        }
        simpanBatas('khusus', cm);
        out[0] = balas('✅ Batas pribadi disimpan.\n' + teksBatasku());
        break;
    }
    case '/berhenti':
        pelanggan = pelanggan.filter(id => id !== chatId);
        global.set('sideban_pelanggan', pelanggan);
        if (warga[kunci]) {
            out[4] = {topic: `sideban/titik01/warga/${warga[kunci].kode}/batas`, payload: ''};  // hapus retained
            delete warga[kunci];
            global.set('sideban_warga', warga);
        }
        out[5] = {payload: 'refresh'};
        out[0] = balas('Kamu tidak akan menerima peringatan lagi. Ketik /daftar untuk mendaftar ulang.');
        out[3] = {payload: pelanggan.length};
        break;
    case '/status':
        out[0] = balas(teksStatus());
        break;
    case '/bisukan':
        if (!admin) { out[0] = balas(TOLAK); break; }
        out[1] = {payload: 'MUTE'};
        out[0] = balas('🔕 Buzzer dibisukan. Buzzer otomatis aktif lagi setelah status kembali AMAN.');
        break;
    case '/aktifkan':
        if (!admin) { out[0] = balas(TOLAK); break; }
        out[1] = {payload: 'AUTO'};
        out[0] = balas('🔔 Buzzer kembali otomatis.');
        break;
    case '/ambang': {
        const s = global.get('sideban_status');
        if (arg.length === 0) {
            const a = (s && s.ambang) || {};
            out[0] = balas(`Ambang saat ini:\nBahaya: jarak ≤ ${a.bahaya} cm\nSiaga: jarak ≤ ${a.siaga} cm\nHujan deras: > ${a.deras}%`);
            break;
        }
        if (!admin) { out[0] = balas(TOLAK); break; }
        if (arg.length !== 3) { out[0] = balas('Format: /ambang <bahaya cm> <siaga cm> <deras %>\nContoh: /ambang 20 100 65'); break; }
        const [b, sg, d] = arg.map(Number);
        const salah = validasiAmbang(b, sg, d);
        if (salah) { out[0] = balas('❌ ' + salah); break; }
        out[2] = {payload: JSON.stringify({bahaya: b, siaga: sg, deras: d})};
        out[0] = balas(`✅ Ambang baru dikirim: bahaya ≤ ${b} cm, siaga ≤ ${sg} cm, deras > ${d}%`);
        break;
    }
    default:
        out[0] = balas('Perintah tidak dikenal. Ketik /bantuan untuk daftar perintah.');
}
return out;

// Peringatan pribadi: bandingkan jarak air dengan batas rumah tiap warga.
// Dikirim sekali saat batas terlampaui, dan sekali saat air turun lagi
// (turun = jarak > batas + 5 cm, supaya tidak spam saat air naik-turun).
const j = Number(msg.payload && msg.payload.jarak_cm);
if (!Number.isFinite(j)) return null;
const JEDA_CM = 5;
const warga = global.get('sideban_warga') || {};
const pelanggan = (global.get('sideban_pelanggan') || []).map(String);
const waktu = new Date().toLocaleString('id-ID', {timeZone: 'Asia/Jakarta'});
const kirim = [];
let berubah = false;

for (const id of Object.keys(warga)) {
    const w = warga[id];
    if (!pelanggan.includes(id)) continue;
    if (!w.terpicu && j <= w.batas_cm) {
        w.terpicu = true; berubah = true;
        kirim.push({payload: {chatId: w.chatId, type: 'message', content:
            `🏠⚠️ PERINGATAN UNTUK RUMAHMU\n` +
            `Air sudah mencapai batas rumah kamu (kategori ${w.kategori}, batas ${w.batas_cm} cm).\n` +
            `Jarak sensor ke air sekarang: ${j} cm\nWaktu: ${waktu}\n\n` +
            `Segera amankan barang di lantai bawah dan pantau terus.`}});
    } else if (w.terpicu && j > w.batas_cm + JEDA_CM) {
        w.terpicu = false; berubah = true;
        kirim.push({payload: {chatId: w.chatId, type: 'message', content:
            `🏠✅ Air sudah turun di bawah batas rumah kamu.\n` +
            `Jarak sensor ke air sekarang: ${j} cm\nWaktu: ${waktu}`}});
    }
}
if (!berubah) return null;
global.set('sideban_warga', warga);
node.status({fill: 'blue', shape: 'dot', text: `${kirim.length} pesan pribadi`});
return [kirim, {payload: 'refresh'}];
